let cur=null; const TL={};
for(const line of techTxt){ if(!line.trim()||line.startsWith('#')) continue;
  if(line.startsWith('@')){cur=line.slice(1).trim(); TL[cur]=[]; continue;}
  const f=line.split('|'); const [l,n,en,rk,role,tags,state,src,home,d,g]=f;
  let rank=rk, canon=true; if(rk.endsWith('*')){rank=rk.slice(0,-1);canon=false;} if(rk==='—'||rk===''){rank=band(+l);canon=false;}
  TL[cur].push({l:+l,n,en,rk:rank,rkc:canon,role,tags:tags?tags.split(','):[],state:state||'',src,home,d:d||'',g:g||''});
}
